-- PT111-S3-Q15. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT111-S3-Q15$batch04$ AND q.stimulus=$batch04$During the recent economic downturn, banks contributed to the decline by loaning less money. Prior to the downturn, regulatory standards for loanmaking by banks were tightened. Clearly, therefore, banks will lend more money if those standards are relaxed.$batch04$ AND q.prompt=$batch04$The argument assumes that$batch04$ AND q.correct_choice=$batch04$A$batch04$) THEN RAISE EXCEPTION 'Question changed: PT111-S3-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT111-S3-Q15$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S3-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT111-S3-Q15$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Banks will lend more money if the regulatory standards are relaxed.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Banks lent less during the downturn. The standards were tightened before the downturn.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The argument assumes the tighter standards caused the drop in lending. What if something else did? The downturn itself could have cut the money banks had to lend.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: rule out another cause of the drop in lending.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT111-S3-Q15$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Negate it: the downturn *did* sharply cut the deposits banks lend from. Then banks lent less because they had less money, and relaxing the standards might not change anything.$batch04$), ($batch04$B$batch04$, $batch04$Whether the standards caused the downturn is a different question from whether they reduced lending.$batch04$), ($batch04$C$batch04$, $batch04$Why the standards were tightened does not affect what relaxing them would do.$batch04$), ($batch04$D$batch04$, $batch04$The stimulus itself says lending fell during this downturn. The author does not assume no downturn comes with less lending.$batch04$), ($batch04$E$batch04$, $batch04$If no relaxation could make up for the downturn, relaxing the standards might not increase lending. That hurts the argument.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT111-S3-Q15$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
